CREATE TABLE el_teacher_availability(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,teacher_id TEXT NOT NULL,weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),from_minute INTEGER NOT NULL CHECK(from_minute BETWEEN 0 AND 1439),to_minute INTEGER NOT NULL CHECK(to_minute BETWEEN 1 AND 1440),is_demo INTEGER NOT NULL DEFAULT 0,CHECK(to_minute>from_minute),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id));
CREATE TABLE el_holidays(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT,date TEXT NOT NULL,name TEXT NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_class_sessions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,group_id TEXT NOT NULL,teacher_id TEXT NOT NULL,classroom_id TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,topic TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','completed','cancelled')),notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_at>starts_at),UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,group_id) REFERENCES el_groups(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id),FOREIGN KEY(org_id,classroom_id) REFERENCES el_classrooms(org_id,id));
CREATE INDEX el_sessions_window ON el_class_sessions(org_id,starts_at,ends_at,status);
CREATE TRIGGER el_session_conflict_insert BEFORE INSERT ON el_class_sessions WHEN NEW.status<>'cancelled' BEGIN
SELECT CASE WHEN EXISTS(SELECT 1 FROM el_class_sessions s WHERE s.org_id=NEW.org_id AND s.status<>'cancelled' AND s.starts_at<NEW.ends_at AND s.ends_at>NEW.starts_at AND (s.teacher_id=NEW.teacher_id OR s.classroom_id=NEW.classroom_id OR s.group_id=NEW.group_id)) THEN RAISE(ABORT,'Schedule conflict: teacher, room or group is already booked') END;
END;
CREATE TRIGGER el_session_conflict_update BEFORE UPDATE ON el_class_sessions WHEN NEW.status<>'cancelled' BEGIN
SELECT CASE WHEN EXISTS(SELECT 1 FROM el_class_sessions s WHERE s.id<>NEW.id AND s.org_id=NEW.org_id AND s.status<>'cancelled' AND s.starts_at<NEW.ends_at AND s.ends_at>NEW.starts_at AND (s.teacher_id=NEW.teacher_id OR s.classroom_id=NEW.classroom_id OR s.group_id=NEW.group_id)) THEN RAISE(ABORT,'Schedule conflict: teacher, room or group is already booked') END;
END;
CREATE TABLE el_attendance(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,session_id TEXT NOT NULL,student_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused','left_early')),arrival INTEGER,departure INTEGER,notes TEXT NOT NULL DEFAULT '',recorded_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(departure IS NULL OR arrival IS NULL OR departure>=arrival),UNIQUE(session_id,student_id),FOREIGN KEY(org_id,session_id) REFERENCES el_class_sessions(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));
CREATE TABLE el_academic_alerts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,student_id TEXT NOT NULL,session_id TEXT NOT NULL,kind TEXT NOT NULL,message TEXT NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(session_id,student_id,kind),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,session_id) REFERENCES el_class_sessions(org_id,id));
CREATE TABLE el_exams(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,group_id TEXT NOT NULL,name TEXT NOT NULL,scheduled_at INTEGER NOT NULL,max_score REAL NOT NULL CHECK(max_score>0),pass_score REAL NOT NULL CHECK(pass_score>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(pass_score<=max_score),UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,group_id) REFERENCES el_groups(org_id,id));
CREATE TABLE el_questions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,exam_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('multiple_choice','true_false','short_answer','essay','matching','fill_blanks')),prompt TEXT NOT NULL,options_json TEXT NOT NULL DEFAULT '[]',correct_answer TEXT NOT NULL DEFAULT '',points REAL NOT NULL CHECK(points>0),position INTEGER NOT NULL DEFAULT 0,is_demo INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(org_id,exam_id) REFERENCES el_exams(org_id,id));
CREATE TRIGGER el_questions_locked_insert BEFORE INSERT ON el_questions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_exams WHERE id=NEW.exam_id AND status='draft') THEN RAISE(ABORT,'Published exam questions are locked') END; END;
CREATE TRIGGER el_questions_locked_update BEFORE UPDATE ON el_questions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_exams WHERE id=NEW.exam_id AND status='draft') THEN RAISE(ABORT,'Published exam questions are locked') END; END;
CREATE TABLE el_exam_results(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,exam_id TEXT NOT NULL,student_id TEXT NOT NULL,score REAL NOT NULL CHECK(score>=0),feedback TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'final' CHECK(status IN ('pending_review','final')),graded_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(exam_id,student_id),FOREIGN KEY(org_id,exam_id) REFERENCES el_exams(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));
CREATE TABLE el_exam_answers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,exam_id TEXT NOT NULL,student_id TEXT NOT NULL,question_id TEXT NOT NULL REFERENCES el_questions(id),answer TEXT NOT NULL,score REAL NOT NULL DEFAULT 0,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(exam_id,student_id,question_id),FOREIGN KEY(org_id,exam_id) REFERENCES el_exams(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));
CREATE INDEX el_attendance_student ON el_attendance(org_id,student_id);
CREATE INDEX el_results_student ON el_exam_results(org_id,student_id,status);
CREATE TRIGGER el_question_delete_lock BEFORE DELETE ON el_questions WHEN OLD.is_demo=0 BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM el_exams WHERE id=OLD.exam_id AND status<>'draft') THEN RAISE(ABORT,'Published exam questions are locked') END; END;
CREATE TRIGGER el_result_guard_insert BEFORE INSERT ON el_exam_results BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_exams WHERE id=NEW.exam_id AND status='published' AND max_score>=NEW.score) THEN RAISE(ABORT,'Exam grading rules changed or exam is closed') END; END;
CREATE TRIGGER el_result_guard_update BEFORE UPDATE ON el_exam_results BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_exams WHERE id=NEW.exam_id AND status='published' AND max_score>=NEW.score) THEN RAISE(ABORT,'Exam grading rules changed or exam is closed') END; END;
